from typing import List

class Solution:
    def findBuildings(self, heights: List[int]) -> List[int]:
        ans = []
        for i in range(len(heights)):
            visible = True
            for j in range(i + 1, len(heights)):
                if heights[j] >= heights[i]:
                    visible = False
                    break
            if visible:
                ans.append(i)
        return ans

