from typing import List

class Solution:
    def findBuildings(self, heights: List[int]) -> List[int]:
        ans = []
        max_right = 0
        for i in range(len(heights) - 1, -1, -1):
            if heights[i] > max_right:
                ans.append(i)
                max_right = heights[i]
        ans.reverse()
        return ans

